"""Authentication primitives for plusquam.

Custom, dependency-free auth:
  * PBKDF2-HMAC-SHA256 password hashing (matches scripts/seed-admin.sh).
  * HS256 JWTs signed with a secret from Secrets Manager (auto-generated by the
    CloudFormation template).

No external packages — uses only the Python standard library + boto3.
"""

from __future__ import annotations

import base64
import hashlib
import hmac
import json
import os
import time

import boto3

# ─── password hashing ─────────────────────────────────────────
PBKDF2_ITERATIONS = 200_000


def hash_password(password: str, salt_hex: str | None = None,
                  iterations: int = PBKDF2_ITERATIONS) -> tuple[str, str, int]:
    """Return (hash_hex, salt_hex, iterations). Generates a salt if none given."""
    salt = bytes.fromhex(salt_hex) if salt_hex else os.urandom(16)
    dk = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, iterations)
    return dk.hex(), salt.hex(), iterations


def verify_password(password: str, salt_hex: str, iterations, expected_hash_hex: str) -> bool:
    if not salt_hex or not expected_hash_hex:
        return False
    try:
        dk = hashlib.pbkdf2_hmac(
            "sha256", password.encode("utf-8"), bytes.fromhex(salt_hex), int(iterations)
        )
    except Exception:
        return False
    return hmac.compare_digest(dk.hex(), expected_hash_hex)


# ─── JWT (HS256) ──────────────────────────────────────────────
_secrets = boto3.client("secretsmanager")
_secret_cache: str | None = None
TOKEN_TTL_SECONDS = 12 * 3600


def get_jwt_secret() -> str:
    global _secret_cache
    if _secret_cache is None:
        secret_id = os.environ["JWT_SECRET_ID"]
        _secret_cache = _secrets.get_secret_value(SecretId=secret_id)["SecretString"]
    return _secret_cache


def _b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def _b64url_decode(s: str) -> bytes:
    return base64.urlsafe_b64decode(s + "=" * (-len(s) % 4))


def jwt_encode(payload: dict, secret: str) -> str:
    header = {"alg": "HS256", "typ": "JWT"}
    seg = (
        _b64url(json.dumps(header, separators=(",", ":")).encode())
        + "."
        + _b64url(json.dumps(payload, separators=(",", ":")).encode())
    )
    sig = hmac.new(secret.encode(), seg.encode(), hashlib.sha256).digest()
    return seg + "." + _b64url(sig)


def jwt_decode(token: str, secret: str) -> dict:
    if not isinstance(token, str) or len(token) > 8_192:
        raise ValueError("malformed token")
    parts = token.split(".")
    if len(parts) != 3:
        raise ValueError("malformed token")
    head, payload_b64, sig = parts
    expected = _b64url(
        hmac.new(secret.encode(), f"{head}.{payload_b64}".encode(), hashlib.sha256).digest()
    )
    if not hmac.compare_digest(expected, sig):
        raise ValueError("bad signature")
    header = json.loads(_b64url_decode(head))
    if header.get("alg") != "HS256" or header.get("typ") != "JWT":
        raise ValueError("unsupported token")
    payload = json.loads(_b64url_decode(payload_b64))
    if not isinstance(payload, dict) or isinstance(payload.get("exp"), bool) or not isinstance(payload.get("exp"), int):
        raise ValueError("invalid expiry")
    if payload["exp"] <= int(time.time()):
        raise ValueError("token expired")
    return payload


def make_token(user: dict) -> str:
    now = int(time.time())
    payload = {
        "sub":   user["userId"],
        "email": user["email"],
        "role":  user.get("role", "user"),
        "name":  user.get("name", ""),
        "ver":   int(user.get("authVersion", 0)),
        "iat":   now,
        "exp":   now + TOKEN_TTL_SECONDS,
    }
    return jwt_encode(payload, get_jwt_secret())


def get_claims(event: dict) -> dict | None:
    """Verify token signature and re-check the current account/role in DynamoDB."""
    headers = event.get("headers") or {}
    auth = headers.get("authorization") or headers.get("Authorization")
    if not auth:
        return None
    token = auth[7:] if auth[:7].lower() == "bearer " else auth
    try:
        claims = jwt_decode(token.strip(), get_jwt_secret())
        if not claims.get("sub") or not claims.get("email"):
            return None
        from lib.ddb import get_user_by_email
        user = get_user_by_email(str(claims["email"]).lower())
        if not user or user.get("userId") != claims.get("sub"):
            return None
        if user.get("accountStatus", "active") != "active":
            return None
        if user.get("role", "user") != claims.get("role", "user"):
            return None
        if int(user.get("authVersion", 0)) != int(claims.get("ver", 0)):
            return None
        return claims
    except Exception:
        return None


def is_admin(claims: dict | None) -> bool:
    return bool(claims) and claims.get("role") == "admin"
